import { test, expect } from '@playwright/test';

test.describe('Search Dropdown Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display dropdown options when typing in the search field', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('test');
    await expect(page.getByRole('listbox')).toBeVisible();
  });

  test('should show relevant options in the dropdown', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('test');
    const dropdownOption = page.getByText(/test option 1/i); // Replace with actual option text
    await expect(dropdownOption).toBeVisible();
  });
});
